/* team structure (93G hmtmstruct/awtmstruct; home DF614, away DF714), 100h bytes */
typedef struct Team {
    short tmshots;               /* 000h team shots: the stats.log dump (DumpStatsLog) prints it under 'shts' */
    short tmppg;                 /* 002h power-play goals: DumpStatsLog 'ppg' column */
    short tmpp;                  /* 004h power plays: DumpStatsLog 'pp' column */
    unsigned char pad_06[0x2];
    short tmpptime;              /* 008h 94G $352 (power-play seconds): updatePPTeamTime adds 1 for the team on the power play (gmode2 bits 5/6) */
    short tmpen;                 /* 00Ah penalties: DumpStatsLog 'pen' column */
    short tmpenmin;              /* 00Ch penalty minutes: DumpStatsLog 'penmin' column */
    short tmATOP;                /* 00Eh 93G $A (attack time of possession stat): chkatop adds 1 once a second for the team with the puck past the blue line */
    short tmscore;               /* 010h 93G $C; Goal adds 1 (inc word [esi+10h]); PeriodOver/clockcont_0 compare hmscore (DF624) with awscore (DF724) */
    unsigned char pad_12[0x14];
    short tmpass;                /* 026h passes: DumpStatsLog 'pass' column */
    short tmpasscomp;            /* 028h completed passes: DumpStatsLog 'passcomp' column */
    short tmline;                /* 02Ah 93G $16; getlchoice adds tmline*4 to the choice index (93G adds tmline*3); lcfound/lcselect store the new line, then setpersonel */
    short tmlcnt;                /* 02Ch 93G none; lcfound/lcselect: when the new line is < 4 it is incremented and wrapped at 3 (even-strength line rotation count) */
    unsigned char pad_2E[0x8];
    short tmap;                  /* 036h 93G $24; getlchoice/lcselect: other tmap - own tmap selects the even / short-handed / power-play choices (93G 'number I'm short') */
    short tmgoalie;              /* 038h 93G $26 (goalie 1/2/none): releasepl picks the priolist row by its sign (93G tst.w tmgoalie(a2) / bpl) */
    unsigned char pad_3A[0xA];
    signed char tmflags;         /* 044h 93G $30; lineinput: bit 0 'start lc mode' cleared before opening the box; lcfound/lcselect clear bit 1 (93G bclr #1,tmflags(a2)) */
    unsigned char pad_45[0x1];
    short tmpde[28];             /* 046h 93G $32 (energy word per roster player, 1000h = full); burst subtracts 0CCh from [tmptr+pnum*2+46h] (93G setpde); reenergizeteam refills 1000h */
    short tmpdst[28];            /* 07Eh 93G $66 (-2 bench / -1 ice / 0+ box): word per roster player: -2 bench, -1 on ice (setplayer, forcepldata), >0 penalty box time; restoreteams sets all */
    signed char tmpbox[36];      /* 0B6h 93G $9A (penalty box list: roster indexes, ends with a negative byte): ProcessPenaltyList walks it and shifts it down */
    unsigned char * tmlines;     /* 0DAh 93G none; pointer to the team's line table (clearteams: home hmlinetab, away awlinetab); getlinee and setpersonel read it */
    unsigned char pad_DE[0x8];
    short * tmplstats;           /* 0E6h pointer to skater stats, 10h bytes per roster player 0-18h (words g, a, pen, +/-, ppg, shg, eng, sht): DumpStatsLog */
    short * tmglstats;           /* 0EAh pointer to goalie stats, 6 bytes per goalie (roster 19h-1Bh; words min, sht, sav): DumpStatsLog */
    unsigned char * tmroster;    /* 0EEh 93G none; pointer to the team roster, 27h bytes per player (byte 0 = status: 3 bench, 4 on ice); clearteams: hmroster / awroster */
    unsigned char pad_F2[0x4];
    struct Player * tmsort;      /* 0F6h 93G $22; pointer to the team's first SortCords entry (home SortCords, away SortCords+300h); forcepldata/resetplstuff walk 6 entries from it */
    unsigned char pad_FA[0x6];
} Team;

